'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import Web3 from 'web3'
import Icon from '../helper/MaterialIcon'
import DefaultPFP from './../public/default-pfp.svg'
import styles from './GiftButton.module.scss'
import Shimmer from '../helper/Shimmer'

export default function GiftButton() {
  const { web3, contract } = initContract()

  const action = async (e, emoji) => {
    const t = toast.loading(`Waiting for transaction's confirmation`)
    const message = prompt(`Please enter a message:`)

    try {
      // window.lukso.request({ method: 'eth_requestAccounts' }).then((accounts) => {
      contract.methods
        .react(`${auth.contextAccounts[0]}`, emoji.emojiId, web3.utils.toHex(message))
        .send({
          from: auth.accounts[0],
          value: emoji.price,
        })
        .then((res) => {
          console.log(res)

          toast.success(`Done`)
          toast.dismiss(t)

          party.confetti(document.body, {
            count: party.variation.range(20, 40),
          })
        })
        .catch((error) => {
          toast.dismiss(t)
        })
      // })
    } catch (error) {
      console.log(error)
      toast.dismiss(t)
    }
  }


  return (
    <button className={`rounded`}>
      Gift
    </button>
  )
}